processParameter.defaultValue:
var autoObject = new tw.object.arrayOf.String();
autoObject[0] = "";
autoObject

TWComponent.script:
if(tw.local.templateID != null && tw.local.templateID.length > 0) {
  var numTemplates = tw.local.templateNames.listLength;
  for(var i = 0; i < numTemplates; i++) {
    if(tw.local.templateID == tw.local.templateNames[i].value) {
      tw.local.templateName = tw.local.templateNames[i].name;
      break;
    }
  }
} else {
  tw.local.templateName = "";
}

tw.local.originalSelectedConditionalActivities = tw.local.selectedConditionalActivities;
tw.local.originalTemplateID = tw.local.templateID;

tw.local.selectedConditionalActivities = new tw.object.listOf.String();
if(tw.local.originalSelectedConditionalActivities != null) {
  var numSelected = tw.local.originalSelectedConditionalActivities.listLength;
  for(var i = 0; i < numSelected; i++) {
    tw.local.selectedConditionalActivities[i] = tw.local.originalSelectedConditionalActivities[i];
  }
}
